-- 040 (اتبعت باسم "038" بس 038 متاخد في الريبو لـ 038_lead_card_fixes):
-- إدخال باقات إنتي لاك (من ملف الباقات). آمن للتكرار (on conflict على packages.name الـ unique).
on conflict (name) do update set description=excluded.description,features=excluded.features,
  duration_months=excluded.duration_months,price_sar=excluded.price_sar,min_price_sar=excluded.min_price_sar,is_active=true;
